class CheckedProblem extends Exception { }
class UncheckedProblem extends RuntimeException { }

public class Main {
    // 検査例外を投げるなら throws が必須
    static void a() throws CheckedProblem {
        throw new CheckedProblem();
    }

    // 非検査例外なら throws は書かなくてよい
    static void b() {
        throw new UncheckedProblem();
    }

    public static void main(String[] args) {
        try {
            a();
        } catch (CheckedProblem e) {
            System.out.println("a() の検査例外を受け止めた");
        }

        // b() は try-catch がなくてもコンパイルできる（実行すると落ちる）
        try {
            b();
        } catch (UncheckedProblem e) {
            System.out.println("b() の非検査例外を受け止めた");
        }
    }
}

