import java.util.Scanner;

class Box implements AutoCloseable {
    private final String name;

    Box(String name) {
        this.name = name;
        System.out.println("開く " + name);
    }

    void put(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("入りません");
        }
        System.out.println(name + "に" + n);
    }

    @Override
    public void close() {
        System.out.println("閉じる " + name);
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();

        try (Box x = new Box("X");
             Box y = new Box("Y");
             Box z = new Box("Z")) {
            x.put(n);
            y.put(n);
            z.put(n);
        } catch (IllegalArgumentException e) {
            System.out.println("エラー");
        } finally {
            System.out.println("おわり");
        }
    }
}

